#!/usr/bin/env bash
# Generated by camcfg.py from arterial_32.yaml; edit the inventory and regenerate instead of editing this file.
# Registers the corridor's 32 camera streams in VST through the VSS API, one
# POST /api/v1/rtsp-streams/add {"sensorUrl": ..., "name": ...} per camera (the same
# records as vst-streams.json). The name is the camera id everywhere else: the TMC spec's
# Assignments and the VA-API calibration.
#
#   H=https://<vss-route-host> ./register-vst-streams.sh            # add
#   H=https://<vss-route-host> ./register-vst-streams.sh --replace  # delete each name first
#
# Register only after the CV pipeline logs "Active sources" (streams added while its engine
# builds are dropped). VST refuses a URL that is already registered under another name.
set -euo pipefail
H="${H:?set H to the VSS route, e.g. https://<vss-route-host>}"
PAUSE_S="${PAUSE_S:-2}"
REPLACE=0
[ "${1:-}" = "--replace" ] && REPLACE=1
while read -r name url; do
  [ -n "$name" ] || continue
  if [ "$REPLACE" = 1 ]; then
    curl -sk -o /dev/null -X DELETE "$H/api/v1/rtsp-streams/delete/$name" || true
  fi
  printf '%s: ' "$name"
  curl -sk -X POST "$H/api/v1/rtsp-streams/add" -H 'Content-Type: application/json' \
    -d "{\"sensorUrl\":\"$url\",\"name\":\"$name\"}"
  echo
  sleep "$PAUSE_S"
done <<'STREAMS'
cam5 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam5
cam6 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam6
cam7 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam7
cam8 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam8
cam9 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam9
cam10 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam10
cam11 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam11
cam12 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam12
cam1 rtsp://rtsp-test-source-cam1.vss.svc.cluster.local:8554/test
cam2 rtsp://rtsp-test-source-cam2.vss.svc.cluster.local:8554/test
cam3 rtsp://rtsp-test-source-cam3.vss.svc.cluster.local:8554/test
cam4 rtsp://rtsp-test-source-cam4.vss.svc.cluster.local:8554/test
cam13 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam13
cam14 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam14
cam15 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam15
cam16 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam16
cam17 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam17
cam18 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam18
cam19 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam19
cam20 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam20
cam21 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam21
cam22 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam22
cam23 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam23
cam24 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam24
cam25 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam25
cam26 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam26
cam27 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam27
cam28 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam28
cam29 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam29
cam30 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam30
cam31 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam31
cam32 rtsp://rtsp-fanout.vss.svc.cluster.local:8554/cam32
STREAMS

# Check: every name listed by VST (name, sensorId, state).
EXPECTED="cam5 cam6 cam7 cam8 cam9 cam10 cam11 cam12 cam1 cam2 cam3 cam4 cam13 cam14 cam15 cam16 cam17 cam18 cam19 cam20 cam21 cam22 cam23 cam24 cam25 cam26 cam27 cam28 cam29 cam30 cam31 cam32"
LIST=$(curl -sk "$H/vst/api/v1/sensor/list")
missing=0
for name in $EXPECTED; do
  if ! printf '%s' "$LIST" | grep -q "\"name\": *\"$name\""; then echo "missing in VST: $name"; missing=$((missing + 1)); fi
done
echo "$(( 32 - missing )) of 32 streams listed by VST"
